---@module 'hl'

--$monitor1 = HDMI-A-1

local monitor1 = "eDP-1"

-- Configure Monitors

hl.monitor({
	output = monitor1,
	mode = "1920x1080@60",
	position = "0x0",
	scale = 1,
})

--monitor=$monitor2,1920x1080@60,0x0,1

-- Workspaces (created on demand, bound to monitor via dispatchers)

hl.on("hyprland.start", function()
	hl.exec_cmd("waybar")
	hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("hyprpaper")
	hl.exec_cmd("hyprctl dispatch workspace 1")
	hl.exec_cmd("hypridle")
	hl.exec_cmd("wl-paste --type text --watch cliphist store")
	hl.exec_cmd("wl-paste --type image --watch cliphist store")
	hl.exec_cmd("hyprctl keyword input:touchpad:middle_button_emulation false")
	hl.exec_cmd("hyprctl keyword input:touchpad:clickfinger_behavior true")

	hl.exec_cmd("/usr/lib/kdeconnectd")
	hl.exec_cmd("kdeconnect-indicator")
end)

-- Source a file (multi-file configs)
-- source = ~/.config/hypr/myColors.conf

-- Set programs that you use

local terminal = "kitty"
local fileManager = "kitty -e yazi"
local menu = "rofi -show drun -config ~/.config/rofi/config.rasi"
local mainMod = "SUPER"

-- Some default env vars.

hl.env("XCURSOR_SIZE", "24")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
