-- Volume Control (using wpctl from Pipewire)

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1.5 @DEFAULT_AUDIO_SINK@ 5%+"))

hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"))

hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"))

-- the mic mute is set differently because this laptop sucks ass

-- Mic mute toggle (Universal)

hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true })

-- Fallback/Custom bind

-- Ensure SUPER+F4 toggles the same microphone nodes as the hardware F4
hl.bind(
	mainMod .. " + " .. "F4",
	hl.dsp.exec_cmd("setsid sh ~/.local/bin/toggle-mic.sh >/dev/null 2>&1 &"),
	{ locked = true }
)

-- Bind plain F4 (hardware key on this device) to toggle microphone mute
-- Toggle both possible microphone nodes (61 and 62) to ensure hardware F4 mutes active source
hl.bind("F4", hl.dsp.exec_cmd("setsid sh ~/.local/bin/toggle-mic.sh >/dev/null 2>&1 &"))

-- Brightness Control (using brightnessctl)

hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl set 5%+"))

hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl set 5%-"))

